import json,pathlib,hashlib
R=pathlib.Path(__file__).resolve().parent;P=R.parent/'workspace'
def load(f):return json.loads((R/f).read_text())
def save(f,x):(R/f).write_text(json.dumps(x,indent=2)+'\n')
# Validate the exact supplied schema subset (no unavailable dependency required).
def validate(v,s,path='$'):
 if 'type' in s:
  types={'object':dict,'array':list,'string':str,'integer':int,'number':(int,float),'boolean':bool}
  assert isinstance(v,types[s['type']]),path
 if 'enum' in s:assert v in s['enum'],path
 if isinstance(v,dict):
  assert set(s.get('required',[]))<=v.keys(),path
  if s.get('additionalProperties') is False:assert v.keys()<=s.get('properties',{}).keys(),path
  for k,sub in s.get('properties',{}).items():
   if k in v:validate(v[k],sub,path+'.'+k)
 if isinstance(v,list):
  assert len(v)>=s.get('minItems',0),path
  for i,x in enumerate(v):validate(x,s.get('items',{}),path+f'[{i}]')
 if isinstance(v,str):assert len(v)>=s.get('minLength',0),path
 if isinstance(v,(int,float)):
  assert v>=s.get('minimum',float('-inf')) and v<=s.get('maximum',float('inf')),path
